: \"1.0.2\",\n    \"@univerjs/docs-thread-comment-ui\": \"1.0.2\",\n    \"@univerjs/docs-ui\": \"1.0.2\",\n    \"@univerjs/drawing\": \"1.0.2\",\n    \"@univerjs/drawing-ui\": \"1.0.2\",\n    \"@univerjs/engine-formula\": \"1.0.2\",\n    \"@univerjs/engine-render\": \"1.0.2\",\n    \"@univerjs/icons\": \"1.38.0\",\n    \"@univerjs/network\": \"1.0.2\",\n    \"@univerjs/protocol\": \"1.0.2\",\n    \"@univerjs/sheets\": \"1.0.2\",\n    \"@univerjs/sheets-conditional-formatting\": \"1.0.2\",\n    \"@univerjs/sheets-conditional-formatting-ui\": \"1.0.2\",\n    \"@univerjs/sheets-crosshair-highlight\": \"1.0.2\",\n    \"@univerjs/sheets-data-validation\": \"1.0.2\",\n    \"@univerjs/sheets-data-validation-ui\": \"1.0.2\",\n    \"@univerjs/sheets-drawing\": \"1.0.2\",\n    \"@univerjs/sheets-drawing-ui\": \"1.0.2\",\n    \"@univerjs/sheets-filter\": \"1.0.2\",\n    \"@univerjs/sheets-filter-ui\": \"1.0.2\",\n    \"@univerjs/sheets-find-replace\": \"1.0.2\",\n    \"@univerjs/sheets-formula\": \"1.0.2\",\n    \"@univerjs/sheets-formula-ui\": \"1.0.2\",\n    \"@univerjs/sheets-hyper-link\": \"1.0.2\",\n    \"@univerjs/sheets-hyper-link-ui\": \"1.0.2\",\n    \"@univerjs/sheets-note\": \"1.0.2\",\n    \"@univerjs/sheets-note-ui\": \"1.0.2\",\n    \"@univerjs/sheets-numfmt\": \"1.0.2\",\n    \"@univerjs/sheets-numfmt-ui\": \"1.0.2\",\n    \"@univerjs/sheets-sort\": \"1.0.2\",\n    \"@univerjs/sheets-sort-ui\": \"1.0.2\",\n    \"@univerjs/sheets-table\": \"1.0.2\",\n    \"@univerjs/sheets-table-ui\": \"1.0.2\",\n    \"@univerjs/sheets-thread-comment\": \"1.0.2\",\n    \"@univerjs/sheets-thread-comment-ui\": \"1.0.2\",\n    \"@univerjs/sheets-ui\": \"1.0.2\",\n    \"@univerjs/thread-comment-ui\": \"1.0.2\",\n    \"@univerjs/ui\": \"1.0.2\",\n    \"@vitejs/plugin-react\": \"6.1.0\",\n    \"busboy\": \"^1.6.0\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"esbuild\": \"^0.28.2\",\n    \"jsdom\": \"^26.1.0\",\n    \"lucide-react\": \"^1.33.0\",\n    \"oxfmt\": \"0.64.0\",\n    \"oxlint\": \"1.79.0\",\n    \"oxlint-tailwindcss\": \"1.10.0\",\n    \"prismjs\": \"1.30.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"rxjs\": \"^7.8.2\",\n    \"simple-git-hooks\": \"^2.13.1\",\n    \"sirv\": \"^3.0.2\",\n    \"tailwind-merge\": \"^3.6.0\",\n    \"tailwindcss\": \"4.3.3\",\n    \"tw-animate-css\": \"^1.4.0\",\n    \"typescript\": \"^7.0.2\",\n    \"vite\": \"^8.2.2\",\n    \"ws\": \"^8.21.3\"\n  },\n  \"simple-git-hooks\": {\n    \"commit-msg\": \"pnpm exec commitlint --edit \\\"$1\\\"\"\n  },\n  \"packageManager\": \"pnpm@11.23.0\"\n}\n"
